// Show food items for the selected hotel
function showFoodItems(hotel) {
    document.getElementById('user-dashboard').classList.add('hidden');
    const foodMenu = document.getElementById('food-menu');
    foodMenu.classList.remove('hidden');
    document.getElementById('menu-title').textContent = `Menu for ${hotel.charAt(0).toUpperCase() + hotel.slice(1)}`;

    const menuItems = document.getElementById('menu-items');
    menuItems.innerHTML = '';

    // Display real menu items based on the selected hotel
    menus[hotel].forEach((foodItem, index) => {
        const foodDiv = document.createElement('div');
        foodDiv.classList.add('food-item');
        foodDiv.innerHTML = `
            <img src="${foodImages[hotel][index]}" alt="${foodItem}" />
            <h4>${foodItem}</h4>
            <button onclick="addToCart('${foodItem}')">Add to Cart</button>
        `;
        menuItems.appendChild(foodDiv);
    });
}

function addToCart(item) {
    cart.push(item);
    localStorage.setItem('cart', JSON.stringify(cart));
    alert(`${item} added to cart!`);
}

function viewCart() {
    document.getElementById('food-menu').classList.add('hidden');
    const cartPage = document.getElementById('cart-page');
    cartPage.classList.remove('hidden');
    const cartItems = document.getElementById('cart-items');
    cartItems.innerHTML = '';

    cart.forEach(item => {
        const listItem = document.createElement('li');
        listItem.textContent = item;
        cartItems.appendChild(listItem);
    });
}
function displayOrderHistory() {
    const orderHistoryContainer = document.getElementById('order-history');
    orderHistoryContainer.innerHTML = '';

    // Check if there's order history for the current user
    if (!orderHistory[currentUser.username] || orderHistory[currentUser.username].length === 0) {
        orderHistoryContainer.innerHTML = '<p>No order history found.</p>';
        return;
    }

    // Display the current user's order history
    orderHistory[currentUser.username].forEach((order, index) => {
        const listItem = document.createElement('li');
        listItem.textContent = `Order ${index + 1}: ${order.join(', ')}`; // Join items for display
        orderHistoryContainer.appendChild(listItem);
    });
}






function checkout() {
    alert('Checkout successful!');

    // Initialize the current user's order history if it doesn't exist
    if (!orderHistory[currentUser.username]) {
        orderHistory[currentUser.username] = []; // Initialize an array for this user
    }

    // Add a clone of the current cart items to the user's order history
    orderHistory[currentUser.username].push(cart.slice()); // Use slice to clone the cart
    localStorage.setItem('orderHistory', JSON.stringify(orderHistory)); // Save to localStorage

    // Clear the cart after checkout
    cart = [];
    localStorage.removeItem('cart'); // Clear cart in localStorage

    displayOrderHistory(); // Display the current user's order history
    document.getElementById('cart-page').classList.add('hidden');
    document.getElementById('user-dashboard').classList.remove('hidden');
}




function goBackToHotels() {
    document.getElementById('food-menu').classList.add('hidden');
    document.getElementById('user-dashboard').classList.remove('hidden');
}

function goBackToMenu() {
    document.getElementById('cart-page').classList.add('hidden');
    document.getElementById('food-menu').classList.remove('hidden');
}
